/**
 * Riff the frog — OpenMascot's third character.
 *
 * Art: ./riff.svg (rig-annotated, generated by scripts/riff-src.py; see
 * docs/rig-format.md). Animations come from the shared library (../library),
 * Riff-only clips, and Riff versions of library clips that move forelimbs
 * (Riff has front legs `arm-*`, not `wing-*`) — see ./clips.ts.
 */
import type { CharacterDef } from '@openmascot/core';
import svg from './art.generated';
import { library } from '../library';
import { riffClips } from './clips';

/** Same expression names as Echo, so `setExpression('happy')` works on every character. */
export const riffExpressions: CharacterDef['expressions'] = {
  neutral: { 'eye-l': 'open', 'eye-r': 'open', mouth: 'default', blush: 'off' },
  happy: { 'eye-l': 'happy', 'eye-r': 'happy', mouth: 'smile' },
  joyful: { 'eye-l': 'happy', 'eye-r': 'happy', mouth: 'open' },
  excited: { 'eye-l': 'open', 'eye-r': 'open', mouth: 'open' },
  love: { 'eye-l': 'happy', 'eye-r': 'happy', mouth: 'smile', blush: 'on' },
  inlove: { 'eye-l': 'heart', 'eye-r': 'heart', mouth: 'open', blush: 'on' },
  unimpressed: { 'eye-l': 'half', 'eye-r': 'half', mouth: 'flat' },
  playful: { 'eye-l': 'open', 'eye-r': 'happy', mouth: 'tongue' },
  wink: { 'eye-l': 'open', 'eye-r': 'happy', mouth: 'smile' },
  determined: { 'eye-l': 'angry', 'eye-r': 'angry', mouth: 'flat' },
  sad: { 'eye-l': 'sad', 'eye-r': 'sad', mouth: 'frown' },
  surprised: { 'eye-l': 'surprised', 'eye-r': 'surprised', mouth: 'o' },
  singing: { 'eye-l': 'open', 'eye-r': 'open', mouth: 'o' },
  dizzy: { 'eye-l': 'dizzy', 'eye-r': 'dizzy', mouth: 'wavy' },
  sleepy: { 'eye-l': 'closed', 'eye-r': 'closed', mouth: 'default' },
  proud: { 'eye-l': 'happy', 'eye-r': 'happy', mouth: 'grin' },
};

export const riff: CharacterDef = {
  id: 'riff',
  name: 'Riff',
  svg,
  expressions: riffExpressions,
  params: {
    /** Look left/right (-1..1): the wide head turns in pseudo-3D, the eye domes parallax, pupils lead. */
    lookX: {
      min: -1.5,
      max: 1.5,
      drives: [
        { bone: 'head', channel: 'yaw', k: 22 },
        { bone: 'head', channel: 'x', k: 3 },
        { bone: 'body', channel: 'yaw', k: 5 },
        // pupils rest against the inner edge of the white, so they mostly travel outward
        { bone: 'pupil-l', channel: 'x', curve: [[-1.5, -8], [0, 0], [1.5, 2]] },
        { bone: 'pupil-r', channel: 'x', curve: [[-1.5, -2], [0, 0], [1.5, 8]] },
      ],
    },
    /** Look up/down (-1..1, + = down). */
    lookY: {
      min: -1.5,
      max: 1.5,
      drives: [
        { bone: 'head', channel: 'pitch', k: 12 },
        { bone: 'head', channel: 'y', k: 2 },
        { bone: 'pupil-l', channel: 'y', k: 5 },
        { bone: 'pupil-r', channel: 'y', k: 5 },
      ],
    },
    /** Eyelid close 0..1. */
    blink: {
      min: 0,
      max: 1,
      drives: [
        { bone: 'eye-l', channel: 'sy', k: -0.9 },
        { bone: 'eye-r', channel: 'sy', k: -0.9 },
      ],
    },
    /** Breathing cycle -1..1: the throat and belly do the breathing on a frog. */
    breathe: {
      drives: [
        { bone: 'body', channel: 'sy', k: 0.012 },
        { bone: 'body', channel: 'sx', k: -0.004 },
        { bone: 'head', channel: 'y', k: -1.4 },
        { bone: 'belly', channel: 'sx', k: 0.012 },
      ],
    },
    /** Squash (+) / stretch (−) from the ground; stretching also unfolds the hind legs a little. */
    squash: {
      min: -1,
      max: 1,
      drives: [
        { bone: 'root', channel: 'sy', k: -0.2 },
        { bone: 'root', channel: 'sx', k: 0.16 },
        { bone: 'leg-l', channel: 'rot', curve: [[-1, -14], [0, 0], [1, 6]] },
        { bone: 'leg-r', channel: 'rot', curve: [[-1, 14], [0, 0], [1, -6]] },
        { bone: 'shin-l', channel: 'rot', curve: [[-1, 18], [0, 0]] },
        { bone: 'shin-r', channel: 'rot', curve: [[-1, -18], [0, 0]] },
      ],
    },
    /**
     * Forelimbs (Riff's front legs stand in for wings): +1 = both arms up and
     * out, 1.5 = overhead; −1 = tucked in toward the belly.
     */
    flap: {
      min: -1.5,
      max: 1.5,
      drives: [
        // raised arms swing out rather than straight up and stretch a little,
        // so they clear the big head instead of vanishing against it
        { bone: 'arm-l', channel: 'rot', curve: [[-1.5, -20], [-1, -14], [0, 0], [1, 74], [1.5, 112]] },
        { bone: 'arm-r', channel: 'rot', curve: [[-1.5, 20], [-1, 14], [0, 0], [1, -74], [1.5, -112]] },
        { bone: 'arm-l', channel: 'sy', curve: [[0, 0], [1, 0.14], [1.5, 0.34]] },
        { bone: 'arm-r', channel: 'sy', curve: [[0, 0], [1, 0.14], [1.5, 0.34]] },
        { bone: 'arm-l', channel: 'y', curve: [[-1.5, -10], [-1, -7], [0, 0]] },
        { bone: 'arm-r', channel: 'y', curve: [[-1.5, -10], [-1, -7], [0, 0]] },
        { bone: 'arm-l', channel: 'dz', curve: [[-1.5, 30], [0, 0]] },
        { bone: 'arm-r', channel: 'dz', curve: [[-1.5, 30], [0, 0]] },
        { bone: 'foot-l', channel: 'rot', curve: [[0, 0], [1, -12], [1.5, -18]] },
        { bone: 'foot-r', channel: 'rot', curve: [[0, 0], [1, 12], [1.5, 18]] },
      ],
    },
    /** Lean the whole body (-1..1 → ±10°). */
    lean: {
      min: -1.5,
      max: 1.5,
      drives: [{ bone: 'body', channel: 'rot', k: 10 }],
    },
    /** Wing-fold (0 spread .. 1 folded) for wing rigs; on Riff it hugs the front legs in. */
    wingFold: {
      min: 0,
      max: 1,
      drives: [
        { bone: 'arm-l', channel: 'rot', k: -10 },
        { bone: 'arm-r', channel: 'rot', k: 10 },
        { bone: 'arm-l', channel: 'x', k: 8 },
        { bone: 'arm-r', channel: 'x', k: -8 },
      ],
    },
  },
  clips: { ...library, ...riffClips },
  anchors: {
    head: { bone: 'head', offset: [0, -100] },
    mouth: { bone: 'mouth' },
    feet: { bone: 'root' },
    throat: { bone: 'throat', offset: [0, 20] },
  },
  idle: {
    clip: 'idle',
    blinkEvery: 3.4,
    fidgetEvery: 7,
    fidgets: ['fidget-eye-bob', 'fidget-look-around', 'fidget-gulp', 'fidget-hop'],
  },
  palette: {
    body: '#8fd003',
    brow: '#7bc301',
    eyeRing: '#a0d80a',
    belly: '#b1e02f',
    legs: '#7bc101',
    smile: '#5fa600',
    throat: '#cdee6c',
  },
  meta: {
    description: 'A laid-back lime-green frog with big bobbing eye domes, a wide smile, a croaking throat pouch and a very long tongue.',
    license: 'MIT',
  },
};

export default riff;
